import React, { useEffect, useState } from 'react';
import axios from 'axios';

const thStyle = { textAlign: 'left', padding: '8px 12px', borderBottom: '1px solid #eee' };
const tdStyle = { padding: '8px 12px', borderBottom: '1px solid #f6f6f6' };
const rowEven = { background: '#fafafa' };
const btnPrimary = { marginRight: 8, padding: '6px 10px', cursor: 'pointer' };
const btnDanger = { padding: '6px 10px', cursor: 'pointer', background: 'transparent', border: '1px solid #e74c3c', color: '#e74c3c' };

const inputStyle = {
  width: '100%',
  padding: '8px',
  boxSizing: 'border-box',
  border: '1px solid #ddd',
  borderRadius: 4
};

function EditForm({ user, onCancel, onSave }) {
  const [form, setForm] = useState({ ...user });
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    setForm({ ...user });
  }, [user]);

  function onChange(e) {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  }

  async function submit(e) {
    e.preventDefault();
    setSaving(true);
    const ok = await onSave(form);
    setSaving(false);
    if (!ok) {
      // ở lại chế độ sửa nếu lỗi
    }
  }

  return (
    <form onSubmit={submit} style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
      <div>
        <label style={{ display: 'block', fontSize: 12 }}>Tên</label>
        <input name="name" value={form.name ?? ''} onChange={onChange} style={inputStyle} />
      </div>

      <div>
        <label style={{ display: 'block', fontSize: 12 }}>Email</label>
        <input name="email" value={form.email ?? ''} onChange={onChange} style={inputStyle} />
      </div>

      <div>
        <label style={{ display: 'block', fontSize: 12 }}>Số điện thoại</label>
        <input name="phone" value={form.phone ?? ''} onChange={onChange} style={inputStyle} />
      </div>

      <div>
        <label style={{ display: 'block', fontSize: 12 }}>Địa chỉ</label>
        <input name="address" value={form.address ?? ''} onChange={onChange} style={inputStyle} />
      </div>

      <div style={{ gridColumn: '1 / span 2', marginTop: 8 }}>
        <button type="submit" disabled={saving} style={{ padding: '8px 12px', marginRight: 8 }}>
          {saving ? 'Đang lưu...' : 'Lưu'}
        </button>
        <button type="button" onClick={onCancel} style={{ padding: '8px 12px' }}>Hủy</button>
      </div>
    </form>
  );
}

function UserList() {
  const [users, setUsers] = useState([]);
  const [editingUser, setEditingUser] = useState(null);

  useEffect(() => {
    axios.get('http://localhost:3000/users').then(res => setUsers(res.data));
  }, []);

  const handleDelete = async (id) => {
    await axios.delete(`http://localhost:3000/users/${id}`);
    setUsers(users.filter(u => u.id !== id));
  };

  const handleSave = async (form) => {
    try {
      await axios.put(`http://localhost:3000/users/${form.id}`, form);
      setUsers(users.map(u => (u.id === form.id ? form : u)));
      setEditingUser(null);
      return true;
    } catch (err) {
      console.error(err);
      return false;
    }
  };

  return (
    <div style={{ padding: 20 }}>
      <h2>Danh sách người dùng</h2>
      <table style={{ borderCollapse: 'collapse', width: '100%', marginTop: 10 }}>
        <thead>
          <tr>
            <th style={thStyle}>Tên</th>
            <th style={thStyle}>Email</th>
            <th style={thStyle}>Số điện thoại</th>
            <th style={thStyle}>Địa chỉ</th>
            <th style={thStyle}>Hành động</th>
          </tr>
        </thead>
        <tbody>
          {users.map((u, i) => (
            <tr key={u.id} style={i % 2 === 0 ? rowEven : {}}>
              <td style={tdStyle}>{u.name}</td>
              <td style={tdStyle}>{u.email}</td>
              <td style={tdStyle}>{u.phone}</td>
              <td style={tdStyle}>{u.address}</td>
              <td style={tdStyle}>
                <button onClick={() => setEditingUser(u)} style={btnPrimary}>Sửa</button>
                <button onClick={() => handleDelete(u.id)} style={btnDanger}>Xóa</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {editingUser && (
        <div style={{ marginTop: 20, padding: 16, border: '1px solid #ccc', borderRadius: 8 }}>
          <h3>Sửa thông tin</h3>
          <EditForm user={editingUser} onCancel={() => setEditingUser(null)} onSave={handleSave} />
        </div>
      )}
    </div>
  );
}

export default UserList;
